import os, json, re

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}

for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

def transform(grid):
    """Transform grid according to observed rule."""
    h, w = len(grid), len(grid[0])

    result = [[0]*w for _ in range(h)]

    # Copy original values
    for r in range(h):
        for c in range(w):
            result[r][c] = grid[r][c]

    # Find all non-zero cells and determine spawn positions
    spawns = []
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != 0:
                # Odd values spawn down, even values spawn left
                if val % 2 == 1:
                    dr = val - 1  # Move down by val-1
                    dc = 0
                else:
                    dr = 0
                    dc = -val  # Move left by val
                spawns.append((r, c, val, dr, dc))

    # Apply spawns (in order so earlier ones don't interfere)
    for sr, sc, val, dr, dc in spawns:
        nr, nc = sr + dr, sc + dc

        if 0 <= nr < h and 0 <= nc < w:
            # Fill rectangle between original and spawn with 5s
            min_r, max_r = min(sr, nr), max(sr, nr)
            min_c, max_c = min(sc, nc), max(sc, nc)

            for fr in range(min_r, max_r + 1):
                for fc in range(min_c, max_c + 1):
                    if (fr, fc) != (sr, sc) and (fr, fc) != (nr, nc):
                        result[fr][fc] = 5

            # Place spawn value
            result[nr][nc] = val

    return result

# Test against demos
print("=== DEMO MATCH TESTS ===")
all_pass = True
for name, inp, out in [('D1', G['Demo pair 1 input'], G['Demo pair 1 output']),
                        ('D2', G['Demo pair 2 input'], G['Demo pair 2 output']),
                        ('D3', G['Demo pair 3 input'], G['Demo pair 3 output'])]:
    pred = transform(inp)
