    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

# Compute displacement for each input cell
def compute_displacement(inp, out):
    disp = []
    for r, row in enumerate(inp):
        for c, val in enumerate(row):
            if val != 0:
                # Find where this spawned
                found = None
                for nr, row_out in enumerate(out):
                    for nc, gval in enumerate(row_out):
                        if gval == val:
                            found = (nr, nc)
