import math

def cells_on_line(p1, p2):
    """Get all integer points on line segment from p1 to p2"""
    r1, c1 = p1
    r2, c2 = p2
    dr, dc = r2-r1, c2-c1

    steps = max(abs(dr), abs(dc))
    if steps == 0: return [p1]

    points = []
    for i in range(steps+1):
        tr = r1 + int((dr * i / steps))
        tc = c1 + int((dc * i / steps))
        points.append((tr, tc))
