        path_counts[sr][sc] += 1
        path_counts[dest_r][dest_c] += 1

        fill_cells = []
        if abs(dr) > 0 and abs(dc) > 0:
            for c in range(min(sc, dest_c), max(sc, dest_c) + 1):
                if (sr, c) != (sr, sc):
                    path_counts[sr][c] += 1
                    fill_cells.append((sr, c))
            for r in range(min(sr, dest_r), max(sr, dest_r) + 1):
                if (r, dest_c) != (sr, sc):
                    path_counts[r][dest_c] += 1
                    fill_cells.append((r, dest_c))
        elif dr != 0:
            for r in range(min(sr, dest_r), max(sr, dest_r) + 1):
                if r != sr:
                    path_counts[r][sc] += 1
                    fill_cells.append((r, sc))
        elif dc != 0:
            for c in range(min(sc, dest_c), max(sc, dest_c) + 1):
                if c != sc:
                    path_counts[sr][c] += 1
                    fill_cells.append((sr, c))

    # Now build result: spawn originals, then fills
    result = [[0]*w for _ in range(h)]
    for sr, sc, sv in sources:
        result[sr][sc] = sv

    # Place spawns
    for sr, sc, sv in sources:
        dr, dc = disp_map.get(sv, (0, 0))
        dest_r, dest_c = sr + dr, sc + dc
        if 0 <= dest_r < h and 0 <= dest_c < w:
            result[dest_r][dest_c] = sv

    # Fill remaining cells: 4 if counted twice, 5 otherwise
    for fr in range(h):
