def compute_transform_v3(grid):
    """Transform with intersection/midpoint/diagonal cascade rules."""
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]

    # Step 1: Identify sources and their properties
    sources = [(r, c, grid[r][c]) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]

    # Track path coverage counts (how many paths cover each cell)
    path_coverage = [[0]*w for _ in range(h)]

    odd_count_paths = []  # Store midpoints of odd-count paths

    # Step 2: Process each source
    for sr, sc, sv in sources:
        dr, dc = disp_map.get(sv, (0, 0))
        dest_r, dest_c = sr + dr, sc + dc

        if not (0 <= dest_r < h and 0 <= dest_c < w):
            continue

        # Get path cells
        path_cells = get_fill_path(sr, sc, dr, dc, h, w)

        # Mark coverage
        for pc in path_cells:
            path_coverage[pc[0]][pc[1]] += 1

        # Check if odd count
        if len(path_cells) % 2 == 1:
            # Find midpoint (middle cell in sorted order)
            sorted_cells = sorted(path_cells, key=lambda p: (abs(p[0]-sr)+abs(p[1]-sc)))
            mid_idx = len(sorted_cells) // 2
            mid_cell = sorted_cells[mid_idx]
            odd_count_paths.append(mid_cell)

        # Place spawn
        if 0 <= dest_r < h and 0 <= dest_c < w:
            result[dest_r][dest_c] = sv

    # Step 3: Find all fill cells and determine values
    result = [[0]*w for _ in range(h)]

    for sr, sc, sv in sources:
        result[sr][sc] = sv

    # Collect all non-origin fill cells
    all_fill_cells = set()
    for sr, sc, sv in sources:
        dr, dc = disp_map.get(sv, (0, 0))
        dest_r, dest_c = sr + dr, sc + dc
        if not (0 <= dest_r < h and 0 <= dest_c < w):
            continue
        all_fill_cells.update(get_fill_path(sr, sc, dr, dc, h, w))

    for fr, fc in all_fill_cells:
        coverage = path_coverage[fr][fc]

        # Rule: If on odd-count path AND at intersection → 4
        # Then propagate diagonally
        if coverage >= 1 and len(odd_count_paths) > 0:
            # Check if this cell is a midpoint of any odd-count path
            is_midpoint = (fr, fc) in odd_count_paths

            # Check if at intersection (appears in multiple paths)
            at_intersection = coverage >= 2

            if is_midpoint or at_intersection:
                result[fr][fc] = 4

            # Propagate 4 diagonally (down-left direction: +1,-1)
            r, c = fr, fc
            while True:
                r_new, c_new = r + 1, c - 1
                if not (0 <= r_new < h and 0 <= c_new < w):
                    break
                if result[r_new][c_new] == 0:
                    result[r_new][c_new] = 4
                else:
                    break
                r, c = r_new, c_new
        else:
            result[fr][fc] = 5

    return result

