def compute_transform_fixed(grid):
    """Transform with correct midpoint detection using ordered path."""
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]

    sources = [(r, c, grid[r][c]) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]

    # Track coverage counts
    path_coverage = [[0]*w for _ in range(h)]

    # Find midpoints of ODD-count paths (by ordered traversal, not distance sort)
    odd_path_midpoints = set()

    for sr, sc, sv in sources:
        dr, dc = disp_map.get(sv, (0, 0))
        dest_r, dest_c = sr + dr, sc + dc

        if not (0 <= dest_r < h and 0 <= dest_c < w):
            continue

        path = get_fill_path_cells(sr, sc, dr, dc, h, w)

        # Remove duplicates
        unique_path = list(set(path))
        unique_path.sort(key=lambda p: (abs(p[0]-sr)+abs(p[1]-sc)))

        # Check odd count (on unique path)
        if len(unique_path) % 2 == 1:
            mid_idx = len(unique_path) // 2
            mid_cell = unique_path[mid_idx]

            # Check if this midpoint also intersects with another path
            path_set = set(unique_path)
            intersects_other = False

            for osr, osc, osv in sources:
                if (osr, osc) == (sr, sc):
                    continue
                odr, odc = disp_map.get(osv, (0,0))
                other_path = set(get_fill_path_cells(osr, osc, odr, odc, h, w))
                if mid_cell in other_path:
                    intersects_other = True
                    break

            if intersects_other:
                odd_path_midpoints.add(mid_cell)

        # Place original
        result[sr][sc] = sv

        # Mark coverage for each cell
        for pc in path:
            path_coverage[pc[0]][pc[1]] += 1

        # Place spawn
        result[dest_r][dest_c] = sv

    # Step 4: Determine fill values
    for fr in range(h):
        for fc in range(w):
            if result[fr][fc] != 0:
                continue

            coverage = path_coverage[fr][fc]

            # Rule: If at intersection (appears in ≥2 paths) OR is odd-midpoint-at-intersection, make 4
            if coverage >= 2 or (fr, fc) in odd_path_midpoints:
                result[fr][fc] = 4
            elif coverage >= 1:
                result[fr][fc] = 5

    # Step 5: Propagate 4 diagonally down-left (+1, -1)
    propagate_4s(result, h, w)

    return result

def propagate_4s(result, h, w):
    """Propagate value 4 diagonally until hitting edge or non-zero."""
    changed = True
    while changed:
        changed = False
        for r in range(h):
            for c in range(w):
                if result[r][c] == 4:
                    nr, nc = r + 1, c - 1
                    if 0 <= nr < h and 0 <= nc < w and result[nr][nc] == 0:
                        result[nr][nc] = 4
                        changed = True

