def compute_transform_complete(grid):
    """Transform with midpoint and diagonal cascade."""
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]

    sources = [(r, c, grid[r][c]) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]
    disp_map_full = {1: (-1, 2), 2: (0, -4), 3: (3, 0), 6: (0, -4)}

    # Track coverage counts
    path_coverage = [[0]*w for _ in range(h)]
    odd_path_midpoints_at_intersection = set()

    # Phase 1: Build paths and detect midpoints/intersections
    for sr, sc, sv in sources:
        dr, dc = disp_map_full.get(sv, (0, 0))
        dest_r, dest_c = sr + dr, sc + dc

        if not (0 <= dest_r < h and 0 <= dest_c < w):
            continue

        path = get_fill_path_cells(sr, sc, dr, dc, h, w)

        # Remove duplicates and sort by distance from source
        unique_path = sorted(set(path), key=lambda p: (abs(p[0]-sr)+abs(p[1]-sc)))

        # Check if path length is odd (unique count)
        if len(unique_path) % 2 == 1:
            mid_idx = len(unique_path) // 2
            mid_cell = unique_path[mid_idx]

            # Check if this midpoint also appears in another path
            path_set = set(unique_path)
            for osr, osc, osv in sources:
                if (osr, osc) == (sr, sc):
                    continue
                odr, odc = disp_map_full.get(osv, (0,0))
                other_path = set(get_fill_path_cells(osr, osc, odr, odc, h, w))
                if mid_cell in other_path:
                    odd_path_midpoints_at_intersection.add(mid_cell)
                    break

        # Place original
        result[sr][sc] = sv

        # Mark coverage for each cell in ALL paths
        for pc in path:
            path_coverage[pc[0]][pc[1]] += 1

        # Place spawn
        result[dest_r][dest_c] = sv

    # Check for diagonal cascade trigger
    def has_mixed_direction_parity(sources_list):
        """Check if all sources are axis-aligned AND have mixed direction parity."""
        all_axis_aligned = True
        row_moves_even = True
        col_moves_even = True

        for sr, sc, sv in sources_list:
            dr, dc = disp_map_full.get(sv, (0, 0))
            if dr != 0 and dc != 0:
                all_axis_aligned = False
                break

            # For non-zero component, check parity
            if dr != 0:
                row_moves_even = row_moves_even and (dr % 2 == 0)
            if dc != 0:
                col_moves_even = col_moves_even and (dc % 2 == 0)

        return all_axis_aligned and (row_moves_even != col_moves_even)

    should_propagate_4s = has_mixed_direction_parity(sources)

    # Phase 2: Determine fill values
    for fr in range(h):
        for fc in range(w):
            if result[fr][fc] != 0:
                continue

            coverage = path_coverage[fr][fc]
            is_intersection = coverage >= 2
            is_odd_midpoint = (fr, fc) in odd_path_midpoints_at_intersection

            if is_intersection or is_odd_midpoint:
                result[fr][fc] = 4
            elif coverage >= 1:
                result[fr][fc] = 5

    # Phase 3: Propagate 4s diagonally down-left (+1, -1)
    # ONLY IF cascade is triggered
    if should_propagate_4s:
        changed = True
        while changed:
            changed = False
            for r in range(h):
                for c in range(w):
                    if result[r][c] == 4:
                        nr, nc = r + 1, c - 1
                        if 0 <= nr < h and 0 <= nc < w and result[nr][nc] == 0:
                            result[nr][nc] = 4
                            changed = True

    return result

print("=== TESTING COMPLETE TRANSFORM ===")
for demo_name in ['Demo pair 1 output', 'Demo pair 2 output', 'Demo pair 3 output']:
    demo_in_key = demo_name.replace('output', 'input')
    expected = G[demo_name]
    pred = compute_transform_complete(G[demo_in_key])

    match = pred == expected
    print(f"\n{demo_name}: {'PASS' if match else 'FAIL'}")
    if not match:
        print("Expected:")
        for row in expected:
