t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
lines = t.split('\n')

G = {}
i = 0
while i < len(lines):
    line = lines[i]
    m = re.match(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\s*$', line)
    if m:
        demo_key = m[1]
        h, w = int(m[2]), int(m[3])
        start_i = i + 1
        rows = []
        j = start_i
        while j < len(lines) and len(rows) < h:
            row_line = lines[j]
            if row_line.strip() and not row_line.startswith('{'):
                parts = row_line.split()
                if len(parts) == w and all(x.isdigit() for x in parts):
                    rows.append(parts)
            j += 1
        if len(rows) == h:
            G[demo_key] = [[int(x) for x in row] for row in rows]
    i += 1

disp_map = {1: (-1, 2), 2: (0, -4), 3: (3, 0), 6: (0, -4)}

def get_fill_path_cells(sr, sc, dr, dc, h, w):
    """Get ordered list of fill cells following L-shape horizontal-first traversal."""
    path = []
    dest_r, dest_c = sr + dr, sc + dc

    if abs(dr) > 0 and abs(dc) > 0:
        # First go horizontally along the row
        for c in range(min(sc, dest_c), max(sc, dest_c) + 1):
            if (sr, c) != (sr, sc):
                path.append((sr, c))
        # Then go vertically along the destination column
        for r in range(min(sr, dest_r), max(sr, dest_r) + 1):
            if (r, dest_c) != (sr, sc):
                path.append((r, dest_c))

    elif dr != 0:
        for r in range(min(sr, dest_r), max(sr, dest_r) + 1):
            if r != sr:
                path.append((r, sc))
    elif dc != 0:
        for c in range(min(sc, dest_c), max(sc, dest_c) + 1):
            if c != sc:
                path.append((sr, c))

    return path

# Test to confirm duplicate issue
