for sr, sc, sv, dr, dc in [(4, 3, 1, -1, 2), (7, 5, 2, 0, -4)]:
    raw_path = get_fill_path_cells(sr, sc, dr, dc, 10, 10)
    unique_sorted = sorted(set(raw_path), key=lambda p: abs(p[0]-sr)+abs(p[1]-sc))
    print(f"Source ({sr},{sc})={sv}, disp=({dr},{dc}):")
    print(f"  Raw path: {raw_path}")
    print(f"  Unique sorted: {unique_sorted}")
    print(f"  Length difference: {len(raw_path)} vs {len(unique_sorted)}")

