def compute_transform_fixed(grid):
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]
    sources = [(r, c, grid[r][c]) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]

    path_coverage = [[0]*w for _ in range(h)]
    intersection_mids = set()

    for sr, sc, sv in sources:
        dr, dc = disp_map.get(sv, (0, 0))
        dest_r, dest_c = sr + dr, sc + dc

        if not (0 <= dest_r < h and 0 <= dest_c < w):
            continue

        raw_path = get_fill_path_cells(sr, sc, dr, dc, h, w)
        unique_path = sorted(set(raw_path), key=lambda p: abs(p[0]-sr)+abs(p[1]-sc))

        if len(unique_path) % 2 == 1:
            mid_idx = len(unique_path) // 2
            mid_cell = unique_path[mid_idx]

            # Check true intersection (midpoint in ALL other paths)
            is_true_int = True
            for osr, osc, osv in sources:
                if (osr, osc) == (sr, sc):
                    continue
                odr, odc = disp_map.get(osv, (0,0))
                other_unique = set(get_fill_path_cells(osr, osc, odr, odc, h, w))
                if mid_cell in other_unique:
                    break
                else:
                    is_true_int = False

            if is_true_int:
                intersection_mids.add(mid_cell)

        result[sr][sc] = sv
        # CRITICAL FIX: Use UNIQUE path for coverage, not raw path!
        for pc in unique_path:
            path_coverage[pc[0]][pc[1]] += 1
        result[dest_r][dest_c] = sv

    def has_both_odd(sources_list):
        for sr, sc, sv in sources_list:
            dr, dc = disp_map.get(sv, (0,0))
            path = get_fill_path_cells(sr, sc, dr, dc, 10, 10)
            if len(set(path)) % 2 == 0:
                return False
        return True

    should_propagate = has_both_odd(sources)

    for fr in range(h):
        for fc in range(w):
            if result[fr][fc] != 0:
                continue
            coverage = path_coverage[fr][fc]
            is_intersection = coverage >= 2
            is_odd_mid = (fr, fc) in intersection_mids

            if is_intersection or is_odd_mid:
                result[fr][fc] = 4
            elif coverage >= 1:
                result[fr][fc] = 5

    if should_propagate:
        changed = True
        while changed:
            changed = False
            for r in range(h):
                for c in range(w):
                    if result[r][c] == 4:
                        nr, nc = r + 1, c - 1
                        if 0 <= nr < h and 0 <= nc < w and result[nr][nc] == 0:
                            result[nr][nc] = 4
                            changed = True

    return result

print("\n\n=== TESTING FIXED TRANSFORM ===")
for demo_name in ['Demo pair 1 output', 'Demo pair 2 output', 'Demo pair 3 output']:
    demo_in = demo_name.replace('output', 'input')
    expected = G[demo_name]
    pred = compute_transform_fixed(G[demo_in])

    match = pred == expected
    print(f"\n{demo_name}: {'PASS' if match else 'FAIL'}")
    if not match:
        print("Expected:")
        for row in expected:
            print(' '.join(map(str, row)))
        print("Got:")
        for row in pred:
            print(' '.join(map(str, row)))

